const crypto = require('crypto');
const secret = $env.AUTOMATION_SERVICE_SECRET;
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const service = headers['x-nexus-service'] || headers['X-Nexus-Service'];
if (service !== 'worker') {
  throw new Error('Unauthorized: Expected X-Nexus-Service: worker');
}

const timestamp = headers['x-nexus-timestamp'] || headers['X-Nexus-Timestamp'];
if (!timestamp) {
  throw new Error('Unauthorized: Missing X-Nexus-Timestamp');
}

const now = Date.now();
const parsedTs = Number(timestamp);
if (isNaN(parsedTs) || Math.abs(now - parsedTs) > 5 * 60 * 1000) {
  throw new Error('Unauthorized: Timestamp skew exceeded 5 minutes');
}

const requestId = headers['x-nexus-request-id'] || headers['X-Nexus-Request-Id'];
if (!requestId) {
  throw new Error('Unauthorized: Missing X-Nexus-Request-Id');
}

const signature = headers['x-nexus-signature'] || headers['X-Nexus-Signature'];
if (!signature) {
  throw new Error('Unauthorized: Missing X-Nexus-Signature');
}

const path = '/webhook/order-paid-email';
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const bodyHash = crypto.createHash('sha256').update(rawBody).digest('hex');
const canonical = [service, 'POST', path, String(timestamp), requestId, bodyHash].join('\n');
const expectedSig = crypto.createHmac('sha256', secret).update(canonical).digest('hex');

if (signature !== expectedSig) {
  throw new Error('Unauthorized: Invalid HMAC signature from worker');
}

return [$input.first()];

