const crypto = require('crypto');
const secret = $env.AUTOMATION_SERVICE_SECRET;
const jobId = $('Webhook Trigger').first().json.body.jobId;
const emailResult = $input.first().json;
const providerMessageId = emailResult.id || 'simulated';

const body = {
  providerMessageId,
  resultJson: {
    sent: true,
    providerMessageId
  }
};

const service = 'n8n';
const timestamp = Date.now().toString();
const requestId = 'cb-ord-' + jobId + '-' + timestamp;
const path = '/v1/internal/automation/jobs/' + jobId + '/complete';
const rawBody = JSON.stringify(body);
const bodyHash = crypto.createHash('sha256').update(rawBody).digest('hex');
const canonical = [service, 'POST', path, timestamp, requestId, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');

return [{
  json: {
    jobId,
    body,
    headers: {
      'Content-Type': 'application/json',
      'X-Nexus-Service': service,
      'X-Nexus-Timestamp': timestamp,
      'X-Nexus-Request-Id': requestId,
      'X-Nexus-Signature': signature,
      'X-Nexus-Signature-Version': 'v1'
    }
  }
}];
